create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text, role text default 'student', progress integer default 0, completed_resources text[] default '{}', practice_attempts integer default 0, saved_resources text[] default '{}', downloads text[] default '{}', created_at timestamptz default now());
create table if not exists public.resources (id bigint generated by default as identity primary key, title text not null, category text not null, subject text default 'Other', year integer, file_url text not null, created_by uuid references auth.users(id), created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.resources enable row level security;
create policy "profiles own read" on public.profiles for select using (auth.uid()=id); create policy "profiles own update" on public.profiles for update using (auth.uid()=id); create policy "resources public read" on public.resources for select using (true); create policy "admins insert resources" on public.resources for insert with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name,role,progress,completed_resources,practice_attempts,saved_resources,downloads) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),'student',0,'{}',0,'{}','{}'); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
